<?php require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';$sub=$id?query_one("SELECT * FROM subscriptions WHERE id=? AND status='pending'",'i',[$id]):null;if($sub&&in_array($action,['approve','reject'],true)){$db=db();$db->begin_transaction();try{if($action==='approve'){$start=date('Y-m-d H:i:s');$end=date('Y-m-d H:i:s',strtotime('+30 days'));$s=$db->prepare("UPDATE subscriptions SET status='active',starts_at=?,expires_at=?,reviewed_by=? WHERE id=?");$aid=$_SESSION['admin']['id'];$s->bind_param('ssii',$start,$end,$aid,$id);$s->execute();$u=$db->prepare('UPDATE users SET subscription_expires_at=GREATEST(COALESCE(subscription_expires_at,NOW()),NOW())+INTERVAL 30 DAY WHERE id=?');$u->bind_param('i',$sub['user_id']);$u->execute();}else{$s=$db->prepare("UPDATE subscriptions SET status='rejected',reviewed_by=? WHERE id=?");$aid=$_SESSION['admin']['id'];$s->bind_param('ii',$aid,$id);$s->execute();}$db->commit();flash('success','Subscription updated.');}catch(Throwable $e){$db->rollback();flash('error','Update failed.');}header('Location: subscriptions.php');exit;}}$pageTitle='Subscriptions';include __DIR__.'/_top.php';$rows=db()->query('SELECT s.*,u.full_name,u.username,p.name FROM subscriptions s JOIN users u ON u.id=s.user_id JOIN subscription_plans p ON p.id=s.plan_id ORDER BY s.id DESC');?><h1>Subscription requests</h1><section class="card scroll"><table><tr><th>Student</th><th>Reference</th><th>Amount</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['full_name'])?> (@<?=e($r['username'])?>)</td><td><?=e($r['payment_method'])?><br><?=e($r['payment_reference'])?></td><td>LKR <?=e($r['amount_lkr'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="good" name="action" value="approve">Approve</button><button class="danger" name="action" value="reject">Reject</button></form><?php endif;?></td></tr><?php endwhile;?></table></section><?php include __DIR__.'/../includes/footer.php';?>
